// Normalización de empresas chilenas. Este mismo código se pega en el nodo
// Code del workflow A (n8n), así que se mantiene sin dependencias externas.

const PERSONA_JURIDICA_MIN = 50000000;

const SUFIJOS_SOCIETARIOS = [
  'sociedad por acciones', 'sociedad anonima', 'sociedad de responsabilidad limitada',
  'empresa individual de responsabilidad limitada', 'limitada', 'ltda', 'spa', 's a', 'sa',
  'eirl', 'e i r l', 'y cia', 'y compania', 'cia',
];

function quitarTildes(texto) {
  return texto.normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// Calcula el dígito verificador de un RUT con el algoritmo módulo 11.
function calcularDV(cuerpo) {
  let suma = 0;
  let multiplicador = 2;
  for (let i = cuerpo.length - 1; i >= 0; i--) {
    suma += Number(cuerpo[i]) * multiplicador;
    multiplicador = multiplicador === 7 ? 2 : multiplicador + 1;
  }
  const resto = 11 - (suma % 11);
  if (resto === 11) return '0';
  if (resto === 10) return 'K';
  return String(resto);
}

// Devuelve { valido, cuerpo, dv, rut, personaJuridica } a partir de "76.123.456-7", "761234567", etc.
function parseRut(entrada) {
  const limpio = String(entrada ?? '').toUpperCase().replace(/[^0-9K]/g, '');
  if (limpio.length < 2) return { valido: false };
  const cuerpo = limpio.slice(0, -1);
  const dv = limpio.slice(-1);
  if (!/^\d+$/.test(cuerpo)) return { valido: false };
  const valido = calcularDV(cuerpo) === dv;
  const numero = Number(cuerpo);
  return {
    valido,
    cuerpo,
    dv,
    rut: `${numero}-${dv}`,
    personaJuridica: numero >= PERSONA_JURIDICA_MIN,
  };
}

// "https://www.Empresa.cl/contacto?x=1" -> "empresa.cl"
function normalizarDominio(entrada) {
  if (!entrada) return null;
  let texto = String(entrada).trim().toLowerCase();
  if (!texto) return null;
  texto = texto.replace(/^[a-z]+:\/\//, '');
  texto = texto.split(/[/?#]/)[0];
  texto = texto.replace(/:\d+$/, '');
  texto = texto.replace(/^www\d*\./, '');
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(texto)) return null;
  return texto;
}

// "Inversiones Pérez & Cía. Ltda." -> "inversiones perez"
function normalizarRazonSocial(entrada) {
  let texto = quitarTildes(String(entrada ?? '').toLowerCase());
  texto = texto.replace(/&/g, ' y ');
  texto = texto.replace(/[^a-z0-9ñ ]/g, ' ').replace(/\s+/g, ' ').trim();
  let cambio = true;
  while (cambio) {
    cambio = false;
    for (const sufijo of SUFIJOS_SOCIETARIOS) {
      if (texto === sufijo) continue;
      if (texto.endsWith(' ' + sufijo)) {
        texto = texto.slice(0, -(sufijo.length + 1)).trim();
        cambio = true;
      }
    }
  }
  return texto;
}

// Clave para detectar duplicados: el RUT manda; si no hay RUT válido, el dominio; si no, el nombre.
function dedupKey({ rut, dominio, razonSocial }) {
  const r = parseRut(rut);
  if (r.valido) return `rut:${r.rut}`;
  const d = normalizarDominio(dominio);
  if (d) return `dom:${d}`;
  const n = normalizarRazonSocial(razonSocial);
  return n ? `nom:${n}` : null;
}

// Palabras que describen el giro y no identifican a una empresa: no sirven solas como dominio
// ni como prueba de que un sitio pertenece a la empresa.
const PALABRAS_GENERICAS = new Set([
  'sociedad', 'inversiones', 'inversion', 'comercial', 'comercializadora', 'servicios', 'empresa',
  'empresas', 'grupo', 'inmobiliaria', 'constructora', 'transportes', 'transporte', 'agricola',
  'ingenieria', 'clinica', 'centro', 'chile', 'chilena', 'holding', 'asesorias', 'consultora',
  'consultores', 'distribuidora', 'importadora', 'exportadora', 'gestion', 'desarrollo',
  'proyectos', 'capital', 'negocios', 'compania', 'corporacion', 'spa', 'limitada', 'del', 'los',
  'las', 'de', 'la', 'el', 'y', 'e', 'en', 'para', 'con',
]);

function palabrasDistintivas(razonSocial) {
  return normalizarRazonSocial(razonSocial)
    .replace(/ñ/g, 'n')
    .split(' ')
    .filter((p) => p.length >= 4 && !PALABRAS_GENERICAS.has(p));
}

// Candidatos de dominio a partir de la razón social:
// "Inversiones Club Exponencial SpA" -> clubexponencial.cl, club-exponencial.cl, exponencial.cl, ...
function candidatosDominio(razonSocial) {
  const palabras = normalizarRazonSocial(razonSocial).replace(/ñ/g, 'n').split(' ').filter(Boolean);
  const sinGiro = palabras.filter((p) => !PALABRAS_GENERICAS.has(p));
  const slugs = new Set();
  if (palabras.length) slugs.add(palabras.join(''));
  if (sinGiro.length) {
    slugs.add(sinGiro.join(''));
    if (sinGiro.length > 1) slugs.add(sinGiro.join('-'));
    if (sinGiro.length > 2) slugs.add(sinGiro.slice(0, 2).join(''));
    if (sinGiro[0].length >= 5) slugs.add(sinGiro[0]);
  }
  const candidatos = [];
  for (const slug of slugs) {
    if (slug.length < 4 || slug.length > 40) continue;
    candidatos.push(`${slug}.cl`, `${slug}.com`);
  }
  return candidatos.slice(0, 8);
}

// Nodo "Parsear y normalizar" (workflow A · Ingesta). Requiere lib/normalize.js antepuesto.
const params = $('Parámetros').first().json;
const existentes = new Set(
  $('Leer claves existentes').all().map((i) => i.json.dedup_key).filter(Boolean)
);

const texto = String($input.first().json.csv || '').replace(/^﻿/, '');
const lineas = texto.split(/\r?\n/).filter((l) => l.trim());
const cabecera = lineas[0].split(';').map((h) => h.trim());
const col = (nombre) => cabecera.indexOf(nombre);
const C = {
  rut: col('RUT'),
  razon: col('Razon Social'),
  anio: col('Anio'),
  comuna: col('Comuna Social'),
  region: col('Region Social'),
  tipo: col('Codigo de sociedad'),
  actuacion: col('Tipo de actuacion'),
  capital: col('Capital'),
};
if (Object.values(C).some((i) => i < 0)) {
  throw new Error('El CSV no tiene las columnas esperadas: ' + cabecera.join(' | '));
}

const regiones = new Set(String(params.regiones).split(',').map((s) => s.trim()));
const capitalMin = Number(params.capital_min) || 0;
const limite = Number(params.limite) || 50;
const excluirHoldings = params.excluir_holdings !== false;

const filas = lineas.slice(1).map((l) => l.split(';'));
const disueltas = new Set();
for (const f of filas) {
  if (/DISOLU/i.test(f[C.actuacion] || '')) disueltas.add(parseRut(f[C.rut]).rut);
}

// Capitales declarados sobre 100 mil millones de CLP en una SpA nueva suelen ser errores de tipeo.
const CAPITAL_ATIPICO = 100000000000;

const stats = { filas: filas.length, constituciones: 0, rut_invalido: 0, persona_natural: 0, eirl: 0,
  disueltas: 0, capital_atipico: 0, fuera_filtro: 0, holdings: 0, duplicadas_csv: 0, ya_existentes: 0 };
const vistas = new Set();
const candidatas = [];

for (const f of filas) {
  if (!/CONSTITU/i.test(f[C.actuacion] || '')) continue;
  stats.constituciones++;
  const rut = parseRut(f[C.rut]);
  if (!rut.valido) { stats.rut_invalido++; continue; }
  if (!rut.personaJuridica) { stats.persona_natural++; continue; }
  if (disueltas.has(rut.rut)) { stats.disueltas++; continue; }
  // Una EIRL tiene un único dueño y su razón social suele ser su nombre completo:
  // se excluye para no tratar datos de personas naturales.
  const tipo = String(f[C.tipo] || '').trim();
  if (/^EIRL$/i.test(tipo) || /INDIVIDUAL DE RESPONSABILIDAD/i.test(f[C.razon] || '')) { stats.eirl++; continue; }
  const capital = Number(String(f[C.capital] || '0').replace(/[^0-9]/g, '')) || 0;
  if (capital > CAPITAL_ATIPICO) { stats.capital_atipico++; continue; }
  const region = String(f[C.region] || '').trim();
  if (capital < capitalMin || !regiones.has(region)) { stats.fuera_filtro++; continue; }
  const razonSocial = String(f[C.razon] || '').trim();
  // Las sociedades de inversión/holdings rara vez tienen sitio ni clientes personas: fuera del ICP.
  if (excluirHoldings && /^(sociedad (de )?)?inversiones\b|\bholding\b|\binversiones\s+(y|e)\s+inversiones\b/i.test(quitarTildes(razonSocial))) {
    stats.holdings++; continue;
  }
  const clave = dedupKey({ rut: rut.rut, razonSocial });
  if (vistas.has(clave)) { stats.duplicadas_csv++; continue; }
  vistas.add(clave);
  if (existentes.has(clave)) { stats.ya_existentes++; continue; }
  candidatas.push({
    rut: rut.rut,
    razon_social: razonSocial,
    nombre_norm: normalizarRazonSocial(razonSocial),
    dedup_key: clave,
    comuna: String(f[C.comuna] || '').trim(),
    region,
    capital,
    anio_constitucion: Number(f[C.anio]) || null,
    tipo_sociedad: tipo,
    fuente: 'RES datos.gob.cl',
    estado: 'nueva',
    run_id: params.run_id,
  });
}

// Primero las de mayor capital: tienen más probabilidad de tener sitio web y presupuesto.
candidatas.sort((a, b) => b.capital - a.capital);
const seleccion = candidatas.slice(0, limite);
const meta = { ...Object.fromEntries(Object.entries(stats).map(([k, v]) => ['meta_' + k, v])),
  meta_candidatas: candidatas.length, meta_seleccionadas: seleccion.length };

if (seleccion.length === 0) return [{ json: { sin_nuevas: true, ...meta } }];
return seleccion.map((e) => ({ json: { sin_nuevas: false, ...e, ...meta } }));

// Nodo "Resumen de ingesta" (workflow A). Arma la fila para la tabla `corridas`.
const params = $('Parámetros').first().json;
const parse = $('Parsear y normalizar').all().map((i) => i.json);
const m = parse[0] || {};
const nuevas = parse.filter((e) => !e.sin_nuevas).length;

return [{
  json: {
    run_id: params.run_id,
    etapa: 'ingesta',
    inicio: params.inicio,
    fin: new Date().toISOString(),
    procesadas: m.meta_constituciones || 0,
    nuevas,
    duplicadas: (m.meta_duplicadas_csv || 0) + (m.meta_ya_existentes || 0),
    excluidas: (m.meta_persona_natural || 0) + (m.meta_rut_invalido || 0) + (m.meta_disueltas || 0) +
      (m.meta_eirl || 0) + (m.meta_capital_atipico || 0),
    errores: 0,
    nota: 'filas=' + (m.meta_filas || 0) + ' fuera_filtro=' + (m.meta_fuera_filtro || 0) +
      ' holdings=' + (m.meta_holdings || 0) +
      ' candidatas=' + (m.meta_candidatas || 0) + ' ya_existentes=' + (m.meta_ya_existentes || 0) +
      ' anio=' + params.anio,
  },
}];
